using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Reflection;
using System.Windows.Forms;
using MelloCharts;

public static class WorkbookDataTests
{
    static int passed, failed;
    const string Ns="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
    const string Rel="http://schemas.openxmlformats.org/officeDocument/2006/relationships";
    static void Test(string name,Action body){try{body();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
    static void Is(bool value,string message){if(!value)throw new Exception(message);}
    static void Reject(Action body){try{body();}catch(ArgumentException){return;}catch(InvalidDataException){return;}throw new Exception("Invalid workbook input accepted");}
    static void Part(ZipArchive zip,string name,string xml){using(StreamWriter writer=new StreamWriter(zip.CreateEntry(name).Open(),new UTF8Encoding(false)))writer.Write(xml);}
    static string Cell(string reference,string value){return "<c r='"+reference+"' t='inlineStr'><is><t>"+value+"</t></is></c>";}
    static string Data(string value){return "<row r='500'>"+Cell("H500","categoria")+Cell("I500","realizado")+Cell("J500","projetado")+Cell("K500","baseline")+"</row><row r='501'><c r='H501' t='s'><v>0</v></c><c r='I501'><f>1+2</f><v>"+value+"</v></c><c r='J501'><v>2.75</v></c><c r='K501'><v>8</v></c></row>";}
    static void Write(string path,string data,bool external){using(FileStream file=new FileStream(path,FileMode.Create,FileAccess.Write,FileShare.ReadWrite))using(ZipArchive zip=new ZipArchive(file,ZipArchiveMode.Create)){
        Part(zip,"xl/workbook.xml","<workbook xmlns='"+Ns+"' xmlns:r='"+Rel+"'><sheets><sheet name='Capa' sheetId='1' r:id='r1'/><sheet name='Dados salvos' sheetId='5' r:id='r5'/></sheets></workbook>");
        Part(zip,"xl/_rels/workbook.xml.rels","<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='r1' Type='"+Rel+"/worksheet' Target='worksheets/first.xml'/><Relationship Id='r5' Type='"+Rel+"/worksheet' Target='worksheets/second.xml'/><Relationship Id='str' Type='"+Rel+"/sharedStrings' Target='sharedStrings.xml'/>"+(external?"<Relationship Id='external' Type='"+Rel+"/hyperlink' TargetMode='External' Target='https://example.com/'/>":"")+"</Relationships>");
        Part(zip,"xl/sharedStrings.xml","<sst xmlns='"+Ns+"'><si><r><t>Equi</t></r><r><t>pamentos</t></r><rPh sb='0' eb='1'><t>ignorar</t></rPh></si></sst>");
        Part(zip,"xl/worksheets/first.xml","<worksheet xmlns='"+Ns+"'><sheetData/></worksheet>");
        Part(zip,"xl/worksheets/second.xml","<worksheet xmlns='"+Ns+"'><dimension ref='A1:XFD1048576'/><sheetData>"+data+"</sheetData></worksheet>");
    }}
    static void Fixture(Action<string> body){string path=Path.Combine(Path.GetTempPath(),"mello-workbook-"+Guid.NewGuid().ToString("N")+".xlsx");try{Write(path,Data("3.125"),false);body(path);}finally{File.Delete(path);}}
    static void AddPart(string path,string name,string xml){using(FileStream file=File.Open(path,FileMode.Open,FileAccess.ReadWrite))using(ZipArchive zip=new ZipArchive(file,ZipArchiveMode.Update))Part(zip,name,xml);}
    static void ReplacePart(string path,string name,string xml){using(FileStream file=File.Open(path,FileMode.Open,FileAccess.ReadWrite))using(ZipArchive zip=new ZipArchive(file,ZipArchiveMode.Update)){ZipArchiveEntry old=zip.GetEntry(name);if(old!=null)old.Delete();Part(zip,name,xml);}}
    [STAThread] public static int Main(){
        Test("lists workbook sheets in source order",delegate{Fixture(delegate(string p){Is(WorkbookData.ListSheets(p).SequenceEqual(new[]{"Capa","Dados salvos"}),"Sheet names/order lost");});});
        Test("imports explicit offset range from second sheet and cached rich text",delegate{Fixture(delegate(string p){ChartDocument d=WorkbookData.Import(p,"Dados salvos","$h$500:$k$501","columns");Is(d.rows.Count==1 && d.rows[0].label=="Equipamentos","Wrong data rectangle or rich text");Is(d.rows[0].actual==3.125 && d.rows[0].forecast==2.75,"Cached invariant numbers lost");Is(d.excelLink.path==Path.GetFullPath(p) && d.excelLink.sheet=="Dados salvos" && d.excelLink.range=="H500:K501","Source is not normalized");});});
        Test("detects used rectangle from actual values instead of formatted dimension",delegate{Fixture(delegate(string p){ChartDocument d=WorkbookData.Import(p,"Dados salvos","","columns");Is(d.excelLink.range=="H500:K501" && d.rows.Count==1,"Incorrect used range");});});
        Test("imports selected data while unrelated values are outside range",delegate{Fixture(delegate(string p){Write(p,Data("3.125")+"<row r='700'>"+Cell("A700","note")+"</row>",false);Is(WorkbookData.Import(p,"Dados salvos","H500:K501","columns").rows.Count==1,"Unrelated cell included");Reject(delegate{WorkbookData.Import(p,"Dados salvos","","columns");});});});
        Test("rejects missing sheet and invalid or missing A1 selections",delegate{Fixture(delegate(string p){Reject(delegate{WorkbookData.Import(p,"Ausente","H500:K501","columns");});foreach(string range in new[]{"A:A","H500","H501:K500","H500:XFD501","A1:D14","'Dados salvos'!H500:K501","H0:K2","H500:K1048577","A1:D2","A1:D1048576"})Reject(delegate{WorkbookData.Import(p,"Dados salvos",range,"columns");});});});
        Test("rejects external relationships anywhere in package",delegate{Fixture(delegate(string p){Write(p,Data("3.125"),true);Reject(delegate{WorkbookData.ListSheets(p);});Reject(delegate{WorkbookData.Import(p,"Dados salvos","H500:K501","columns");});});});
        Test("rejects suspicious cell refs duplicates and uncached formulas",delegate{Fixture(delegate(string p){foreach(string data in new[]{Data("3.125").Replace("r='I501'","r='I500'"),Data("3.125").Replace("r='J501'","r='I501'"),Data("3.125").Replace("<v>3.125</v>",""),Data("3.125").Replace("r='I501'","r='XFE501'")}){Write(p,data,false);Reject(delegate{WorkbookData.Import(p,"Dados salvos","H500:K501","columns");});}});});
        Test("uses saved workbook when Excel holds write sharing",delegate{Fixture(delegate(string p){using(FileStream held=new FileStream(p,FileMode.Open,FileAccess.ReadWrite,FileShare.ReadWrite)){Is(WorkbookData.Import(p,"Dados salvos","H500:K501","columns").rows[0].actual==3.125,"Unable to import shared saved workbook");}});});
        Test("refresh replaces rows without mutating original or appearance",delegate{Fixture(delegate(string p){ChartDocument current=WorkbookData.Import(p,"Dados salvos","H500:K501","columns");current.title="Diretoria";current.subtitle="Revisão";current.source="Controladoria";current.unit="USD";current.style="dark";current.palette="forest";current.decimals=2;current.showLabels=false;current.showGrid=false;current.compactNumbers=true;current.customColors=new ChartColors();string before=ChartCore.Serialize(current);Write(p,Data("77.25"),false);ChartDocument next=WorkbookData.Refresh(current);Is(next.rows[0].actual==77.25,"Saved source was not refreshed");Is(ChartCore.Serialize(current)==before,"Refresh mutated original");Is(next.title=="Diretoria" && next.subtitle=="Revisão" && next.source=="Controladoria" && next.unit=="USD" && next.style=="dark" && next.palette=="forest" && next.decimals==2 && !next.showLabels && !next.showGrid && next.compactNumbers,"Presentation lost on refresh");});});
        Test("failed refresh leaves current document unchanged",delegate{Fixture(delegate(string p){ChartDocument current=WorkbookData.Import(p,"Dados salvos","H500:K501","columns");string before=ChartCore.Serialize(current);Write(p,Data(""),false);Reject(delegate{WorkbookData.Refresh(current);});Is(ChartCore.Serialize(current)==before,"Failed refresh changed document");});});
        Test("source link survives project serialization",delegate{Fixture(delegate(string p){ChartDocument d=ChartCore.Clone(WorkbookData.Import(p,"Dados salvos","H500:K501","columns"));Is(d.excelLink!=null && d.excelLink.sheet=="Dados salvos" && d.excelLink.range=="H500:K501","Project discarded link");});});
        Test("permits internal drawing relationships relative to sheet folder",delegate{Fixture(delegate(string p){AddPart(p,"xl/worksheets/_rels/second.xml.rels","<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='drawing' Type='"+Rel+"/drawing' Target='../drawings/drawing1.xml'/></Relationships>");Is(WorkbookData.Import(p,"Dados salvos","H500:K501","columns").rows[0].actual==3.125,"Internal relationship rejected");});});
        Test("normalizes numeric gantt dates from 1904 workbooks and preserves ISO dates",delegate{Fixture(delegate(string p){
            Write(p,"<row r='500'>"+Cell("H500","categoria")+Cell("I500","data inicial")+Cell("J500","data final")+Cell("K500","progresso")+"</row><row r='501'>"+Cell("H501","Tarefa")+"<c r='I501'><v>0</v></c><c r='J501'><v>2</v></c><c r='K501'><v>25</v></c></row><row r='502'>"+Cell("H502","ISO")+Cell("I502","2026-10-01")+Cell("J502","2026-10-03")+"<c r='K502'><v>50</v></c></row>",false);
            ReplacePart(p,"xl/workbook.xml","<workbook xmlns='"+Ns+"' xmlns:r='"+Rel+"'><workbookPr date1904='1'/><sheets><sheet name='Dados salvos' sheetId='5' r:id='r5'/></sheets></workbook>");
            ChartDocument d=WorkbookData.Import(p,"Dados salvos","H500:K502","gantt");Is(d.rows[0].startDate=="1904-01-01" && d.rows[0].endDate=="1904-01-03","1904 numeric dates changed epoch");Is(d.rows[1].startDate=="2026-10-01" && d.rows[1].endDate=="2026-10-03" && d.rows[1].progress==50,"ISO dates/progress altered");
        });});
        Test("scales only numeric gantt progress with an active percent format",delegate{Fixture(delegate(string p){
            StringBuilder rows=new StringBuilder("<row r='500'>"+Cell("H500","categoria")+Cell("I500","inicio")+Cell("J500","fim")+Cell("K500","progresso")+"</row>");
            for(int i=0;i<5;i++){int r=501+i;rows.Append("<row r='").Append(r).Append("'>").Append(Cell("H"+r,"Tarefa "+i)).Append(Cell("I"+r,"2026-10-01")).Append(Cell("J"+r,"2026-10-03")).Append("<c r='K").Append(r).Append("' s='").Append(i).Append("'><v>0.5</v></c></row>");}
            Write(p,rows.ToString(),false);AddPart(p,"xl/styles.xml","<styleSheet xmlns='"+Ns+"'><numFmts count='3'><numFmt numFmtId='164' formatCode='0.0%'/><numFmt numFmtId='165' formatCode='0.0\\%'/><numFmt numFmtId='166' formatCode='&quot;literal%&quot;0'/></numFmts><cellXfs count='5'><xf numFmtId='0'/><xf numFmtId='9'/><xf numFmtId='164'/><xf numFmtId='165'/><xf numFmtId='166'/></cellXfs></styleSheet>");
            ChartDocument d=WorkbookData.Import(p,"Dados salvos","H500:K505","gantt");double[] expected={0.5,50,50,0.5,0.5};for(int i=0;i<expected.Length;i++)Is(d.rows[i].progress==expected[i],"Incorrect progress for style "+i+": "+d.rows[i].progress);
        });});
        Test("selected table ignores error and uncached formula cells outside selection",delegate{Fixture(delegate(string p){Write(p,Data("3.125")+"<row r='900'><c r='A900' t='e'><v>#DIV/0!</v></c><c r='B900'><f>NOW()</f></c></row>",false);Is(WorkbookData.Import(p,"Dados salvos","H500:K501","columns").rows[0].actual==3.125,"Unselected values blocked import");});});
        Test("rejects DTD duplicate parts and excessive ZIP parts",delegate{Fixture(delegate(string p){
            ReplacePart(p,"xl/workbook.xml","<!DOCTYPE workbook [<!ENTITY x 'bad'>]><workbook xmlns='"+Ns+"'>&x;</workbook>");Reject(delegate{WorkbookData.ListSheets(p);});Write(p,Data("3.125"),false);AddPart(p,"xl/workbook.xml","<workbook xmlns='"+Ns+"'/>");Reject(delegate{WorkbookData.ListSheets(p);});Write(p,Data("3.125"),false);for(int i=0;i<253;i++)AddPart(p,"extra/"+i+".xml","<x/>");Reject(delegate{WorkbookData.ListSheets(p);});
        });});
        Test("import form requires valid preview and invalidates acceptance after range edits",delegate{Fixture(delegate(string p){using(WorkbookImportForm form=new WorkbookImportForm("columns")){
            BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;Func<string,object> field=name=>form.GetType().GetField(name,flags).GetValue(form);Action<string> call=name=>form.GetType().GetMethod(name,flags).Invoke(form,null);
            form.SetPath(p);((ComboBox)field("sheet")).SelectedIndex=1;((TextBox)field("range")).Text="H500:K501";Is(!((Button)field("confirm")).Enabled,"Import enabled before preview");call("LoadPreview");Is(((Button)field("confirm")).Enabled && ((DataGridView)field("table")).Rows.Count==1,"Valid preview did not enable import");((TextBox)field("range")).Text="H500:K500";Is(!((Button)field("confirm")).Enabled,"Stale preview can be imported");call("LoadPreview");Is(!((Button)field("confirm")).Enabled && form.Result==null,"Invalid table can be imported");((TextBox)field("range")).Text="H500:K501";call("LoadPreview");call("AcceptImport");Is(form.Result!=null && form.Result.excelLink.range=="H500:K501" && form.DialogResult==DialogResult.OK,"Validated result not returned");
        }});});
        Test("imports at scatter capacity without silently truncating extra rows",delegate{Fixture(delegate(string p){StringBuilder rows=new StringBuilder("<row r='500'>"+Cell("H500","categoria")+Cell("I500","x")+Cell("J500","y")+"</row>");for(int i=1;i<=80;i++){int r=500+i;rows.Append("<row r='").Append(r).Append("'>").Append(Cell("H"+r,"Ponto "+i)).Append("<c r='I").Append(r).Append("'><v>").Append(i).Append("</v></c><c r='J").Append(r).Append("'><v>3.5</v></c></row>");}Write(p,rows.ToString(),false);ChartDocument d=WorkbookData.Import(p,"Dados salvos","H500:J580","scatter");Is(d.rows.Count==80 && d.rows[79].x==80 && d.rows[79].y==3.5,"Scatter rows lost");Reject(delegate{WorkbookData.Import(p,"Dados salvos","H500:J581","scatter");});});});
        Test("enforces input per-part and total decompression limits",delegate{Fixture(delegate(string p){using(FileStream file=File.Open(p,FileMode.Open,FileAccess.Write))file.SetLength(10000001);Reject(delegate{WorkbookData.ListSheets(p);});Write(p,Data("3.125"),false);AddPart(p,"extra/large.xml",new String('x',8000001));Reject(delegate{WorkbookData.ListSheets(p);});Write(p,Data("3.125"),false);string large=new String('x',8000000);for(int i=0;i<3;i++)AddPart(p,"extra/"+i+".xml",large);Reject(delegate{WorkbookData.ListSheets(p);});});});
        Test("real import identifies saved Excel source",delegate{Fixture(delegate(string p){Is(WorkbookData.Import(p,"Dados salvos","H500:K501","columns").source=="Excel · Dados salvos · H500:K501","Real data labelled as fictitious");});});
        Test("refresh preserves numeric categories displayed as month dates and zero padded IDs",delegate{Fixture(delegate(string p){
            Write(p,"<row r='500'>"+Cell("H500","categoria")+Cell("I500","valor")+"</row><row r='501'><c r='H501' s='1'><v>45678</v></c><c r='I501'><v>5</v></c></row><row r='502'><c r='H502' s='2'><v>123</v></c><c r='I502'><v>8</v></c></row><row r='503'><c r='H503' s='3'><v>45678</v></c><c r='I503'><v>9</v></c></row>",false);
            AddPart(p,"xl/styles.xml","<styleSheet xmlns='"+Ns+"'><numFmts><numFmt numFmtId='164' formatCode='mmm/yyyy'/><numFmt numFmtId='165' formatCode='000000'/><numFmt numFmtId='166' formatCode='dd/MM/yyyy'/></numFmts><cellXfs><xf numFmtId='0'/><xf numFmtId='164'/><xf numFmtId='165'/><xf numFmtId='166'/></cellXfs></styleSheet>");
            CultureInfo old=CultureInfo.CurrentCulture;try{System.Threading.Thread.CurrentThread.CurrentCulture=CultureInfo.GetCultureInfo("pt-BR");ChartDocument initial=WorkbookData.Import(p,"Dados salvos","H500:I503","pie");ChartDocument refreshed=WorkbookData.Refresh(initial);Is(refreshed.rows[0].label=="jan/2025" && refreshed.rows[1].label=="000123" && refreshed.rows[2].label=="21/01/2025","Formatted category labels lost: "+String.Join(" | ",refreshed.rows.Select(r=>r.label).ToArray()));}finally{System.Threading.Thread.CurrentThread.CurrentCulture=old;}
        });});
        Test("category date display respects workbook 1904 epoch",delegate{Fixture(delegate(string p){
            Write(p,"<row r='500'>"+Cell("H500","categoria")+Cell("I500","valor")+"</row><row r='501'><c r='H501' s='1'><v>0</v></c><c r='I501'><v>5</v></c></row>",false);ReplacePart(p,"xl/workbook.xml","<workbook xmlns='"+Ns+"' xmlns:r='"+Rel+"'><workbookPr date1904='1'/><sheets><sheet name='Dados salvos' sheetId='5' r:id='r5'/></sheets></workbook>");AddPart(p,"xl/styles.xml","<styleSheet xmlns='"+Ns+"'><numFmts><numFmt numFmtId='164' formatCode='dd/MM/yyyy'/></numFmts><cellXfs><xf numFmtId='0'/><xf numFmtId='164'/></cellXfs></styleSheet>");Is(WorkbookData.Import(p,"Dados salvos","H500:I501","pie").rows[0].label=="01/01/1904","Wrong category epoch");
        });});
        Test("unsupported numeric category display fails instead of silently changing label",delegate{Fixture(delegate(string p){
            Write(p,"<row r='500'>"+Cell("H500","categoria")+Cell("I500","valor")+"</row><row r='501'><c r='H501' s='1'><v>123</v></c><c r='I501'><v>5</v></c></row>",false);AddPart(p,"xl/styles.xml","<styleSheet xmlns='"+Ns+"'><numFmts><numFmt numFmtId='164' formatCode='&quot;ID-&quot;000'/></numFmts><cellXfs><xf numFmtId='0'/><xf numFmtId='164'/></cellXfs></styleSheet>");Reject(delegate{WorkbookData.Import(p,"Dados salvos","H500:I501","pie");});
        });});
        Test("supports standard built in Excel category date and time styles",delegate{Fixture(delegate(string p){
            StringBuilder rows=new StringBuilder("<row r='500'>"+Cell("H500","categoria")+Cell("I500","valor")+"</row>"),styles=new StringBuilder("<styleSheet xmlns='"+Ns+"'><cellXfs><xf numFmtId='0'/>");for(int i=0;i<9;i++){int r=501+i;rows.Append("<row r='").Append(r).Append("'><c r='H").Append(r).Append("' s='").Append(i+1).Append("'><v>45678.75</v></c><c r='I").Append(r).Append("'><v>5</v></c></row>");styles.Append("<xf numFmtId='").Append(14+i).Append("'/>");}styles.Append("</cellXfs></styleSheet>");Write(p,rows.ToString(),false);AddPart(p,"xl/styles.xml",styles.ToString());
            CultureInfo old=CultureInfo.CurrentCulture;try{System.Threading.Thread.CurrentThread.CurrentCulture=CultureInfo.GetCultureInfo("pt-BR");ChartDocument d=WorkbookData.Import(p,"Dados salvos","H500:I509","pie");string[] expected={"21/01/2025","21-jan-25","21-jan","jan-25","6:00 PM","6:00:00 PM","18:00","18:00:00","21/01/2025 18:00"};for(int i=0;i<expected.Length;i++)Is(d.rows[i].label==expected[i],"Built in style "+(14+i)+" rendered "+d.rows[i].label);}finally{System.Threading.Thread.CurrentThread.CurrentCulture=old;}
        });});
        Test("gantt atividade alias preserves formatted numeric category",delegate{Fixture(delegate(string p){
            Write(p,"<row r='500'>"+Cell("H500","atividade")+Cell("I500","inicio")+Cell("J500","fim")+Cell("K500","progresso")+"</row><row r='501'><c r='H501' s='1'><v>123</v></c>"+Cell("I501","2026-10-01")+Cell("J501","2026-10-03")+"<c r='K501'><v>50</v></c></row>",false);AddPart(p,"xl/styles.xml","<styleSheet xmlns='"+Ns+"'><numFmts><numFmt numFmtId='164' formatCode='000000'/></numFmts><cellXfs><xf numFmtId='0'/><xf numFmtId='164'/></cellXfs></styleSheet>");Is(WorkbookData.Import(p,"Dados salvos","H500:K501","gantt").rows[0].label=="000123","Atividade alias bypasses category formatting");
        });});
        Console.WriteLine(passed+" passed; "+failed+" failed");return failed==0?0:1;
    }
}
